    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the depth-first search
    stack = [(start, [start])]
    while stack:
        (vertex, path) = stack.pop()

        # If this is a leaf node, it means we have reached a dead end
        if vertex not in graph:
